add("vsa1", ("समीकरण संतुलित कीजिए: {0}", "સમીકરણ સમતોલિત કરો: {0}"), {1: ("जाँच: Al 4 = 4, O 6 = 6।", "ચકાસણી: Al 4 = 4, O 6 = 6.")})
add("vsa2", ("लेड नाइट्रेट का क्रिस्टल गर्म करने पर भूरा धुआँ क्यों देता है? समीकरण लिखिए।", "લેડ નાઇટ્રેટનો સ્ફટિક ગરમ કરતાં બદામી ધુમાડો કેમ આપે છે? સમીકરણ લખો."),
    {0: ("गर्म करने पर लेड नाइट्रेट वियोजित होकर नाइट्रोजन डाइऑक्साइड देता है, जो भूरी गैस है:", "ગરમ કરતાં લેડ નાઇટ્રેટ વિઘટન પામીને નાઇટ્રોજન ડાયૉક્સાઇડ આપે છે, જે બદામી વાયુ છે:")})
add("sa1", ("एक विद्यार्थी लोहे की कील को कॉपर सल्फ़ेट विलयन में और ज़िंक की छड़ को आयरन सल्फ़ेट विलयन में डुबोती है। 20 मिनट बाद वह प्रत्येक में क्या देखती है? समीकरण लिखिए।", "એક વિદ્યાર્થિની લોખંડની ખીલીને કૉપર સલ્ફેટના દ્રાવણમાં અને ઝિંકનો સળિયો આયર્ન સલ્ફેટના દ્રાવણમાં ડુબાડે છે. 20 મિનિટ પછી તે દરેકમાં શું જુએ છે? સમીકરણ લખો."),
    {0: ("लोहे की कील: कॉपर की भूरी परत चढ़ती है और नीला विलयन हल्का हरा हो जाता है। {0}", "લોખંડની ખીલી: કૉપરનું બદામી પડ ચડે છે અને વાદળી દ્રાવણ આછું લીલું થાય છે. {0}"),
     1: ("ज़िंक की छड़: ज़िंक लोहे से अधिक अभिक्रियाशील है, इसलिए लोहे को विस्थापित करता है; हल्का हरा विलयन रंगहीन हो जाता है। {0}", "ઝિંકનો સળિયો: ઝિંક લોખંડ કરતાં વધુ સક્રિય છે, તેથી લોખંડને વિસ્થાપિત કરે છે; આછું લીલું દ્રાવણ રંગવિહીન થાય છે. {0}"),
     2: ("दोनों विस्थापन अभिक्रियाएँ हैं।", "બંને વિસ્થાપન પ્રક્રિયાઓ છે.")})
add("sa2", ("अभिक्रिया {0} में (i) उपचयित (ii) अपचयित पदार्थ तथा (iii) उपचायक का नाम बताइए।", "પ્રક્રિયા {0} માં (i) જેનું ઑક્સિડેશન થાય છે (ii) જેનું રિડક્શન થાય છે તે પદાર્થ અને (iii) ઑક્સિડેશનકર્તાનું નામ આપો."),
    {0: ("(i) HCl उपचयित होता है: यह हाइड्रोजन खोकर क्लोरीन देता है।", "(i) HCl નું ઑક્સિડેશન થાય છે: તે હાઇડ્રોજન ગુમાવીને ક્લોરિન આપે છે."), 1: ("(ii) MnO₂ अपचयित होता है: यह ऑक्सीजन खोता है।", "(ii) MnO₂ નું રિડક્શન થાય છે: તે ઑક્સિજન ગુમાવે છે."),
     2: ("(iii) MnO₂ उपचायक है, क्योंकि यह HCl को उपचयित करता है।", "(iii) MnO₂ ઑક્સિડેશનકર્તા છે, કારણ કે તે HCl નું ઑક્સિડેશન કરે છે.")})
add("la1", ("जल के विद्युत अपघटन को दर्शाने वाले क्रियाकलाप का वर्णन कीजिए। प्रत्येक इलेक्ट्रोड पर कौन-सी गैस एकत्रित होती है, और किस अनुपात में? तनु सल्फ़्यूरिक अम्ल की कुछ बूँदें क्यों मिलाई जाती हैं? आप गैसों का परीक्षण कैसे करेंगे?",
            "પાણીનું વિદ્યુતવિભાજન દર્શાવતી પ્રવૃત્તિ વર્ણવો. દરેક ઇલેક્ટ્રોડ પર કયો વાયુ એકત્ર થાય છે, અને કયા ગુણોત્તરમાં? મંદ સલ્ફ્યુરિક ઍસિડનાં થોડાં ટીપાં કેમ ઉમેરવામાં આવે છે? તમે વાયુઓની કસોટી કેવી રીતે કરશો?"),
    {0: ("एक प्लास्टिक के मग के तल में दो कार्बन इलेक्ट्रोड लगाइए और उन्हें 6 V की बैटरी से जोड़िए। इलेक्ट्रोडों पर जल से भरी दो परखनलियाँ उल्टी रखिए।", "પ્લાસ્ટિકના મગના તળિયે બે કાર્બન ઇલેક્ટ્રોડ લગાવો અને તેમને 6 V ની બૅટરી સાથે જોડો. ઇલેક્ટ્રોડ પર પાણી ભરેલી બે કસનળીઓ ઊંધી મૂકો."),
     1: ("तनु सल्फ़्यूरिक अम्ल की कुछ बूँदें मिलाइए: शुद्ध जल विद्युत का बहुत कम चालन करता है।", "મંદ સલ્ફ્યુરિક ઍસિડનાં થોડાં ટીપાં ઉમેરો: શુદ્ધ પાણી વિદ્યુતનું બહુ ઓછું વહન કરે છે."),
     2: ("दोनों इलेक्ट्रोडों पर बुलबुले बनते हैं: कैथोड (ऋण) पर हाइड्रोजन और ऐनोड (धन) पर ऑक्सीजन।", "બંને ઇલેક્ટ્રોડ પર પરપોટા બને છે: કૅથોડ (ઋણ) પર હાઇડ્રોજન અને ઍનોડ (ધન) પર ઑક્સિજન."),
     3: ("हाइड्रोजन का आयतन ऑक्सीजन का दोगुना होता है: {0}", "હાઇડ્રોજનનું કદ ઑક્સિજન કરતાં બમણું હોય છે: {0}"),
     4: ("जलती मोमबत्ती के पास हाइड्रोजन पॉप की ध्वनि के साथ जलती है; ऑक्सीजन सुलगती तीली को जला देती है।", "સળગતી મીણબત્તી પાસે હાઇડ્રોજન 'પૉપ' અવાજ સાથે સળગે છે; ઑક્સિજન ધીમે સળગતી સળીને ભભૂકાવી દે છે.")})
